                    householdName: nil,
                    domain: .shopping,
                    changeCount: shoppingCount,
                    shoppingTitles: shoppingTitles,
                    preservesShoppingTitles: shoppingPreservesTitles && !shoppingTitles.isEmpty
                )
            )
        }

        if !taskIDs.isEmpty {
            descriptors.append(
