                    householdId: householdId,
                    householdName: nil,
                    domain: .tasks,
                    changeCount: taskIDs.count
                )
            )
        }

        if !ideaIDs.isEmpty {
            descriptors.append(
                PassiveSharedActivityAlertDescriptor(
                    householdId: householdId,
                    householdName: nil,
                    domain: .ideas,
                    changeCount: ideaIDs.count
                )
            )
        }

        return descriptors
    }

